#include <cuda_runtime.h>
#include "../bonds-cuda/bondsKernelsGpu.cu"
#include "study_cases.h"
#include <vector>
#include <fstream>
#include <stdexcept>
#include <chrono>
#include <cstdio>
#include <cstring>
#include <cmath>
static_assert(sizeof(bondsDateStruct)==16&&sizeof(bondStruct)==36&&sizeof(bondsYieldTermStruct)==64&&sizeof(couponStruct)==52);
#define CK(x) do{if((x)!=cudaSuccess)throw std::runtime_error(#x);}while(0)
const int G=16;const unsigned GUARD=0x4a5a5a5a;
float fp(unsigned u){float v;memcpy(&v,&u,4);return v;}unsigned bits(float v){unsigned u;memcpy(&u,&v,4);return u;}
template<class T>std::vector<T>readv(const char*name){std::ifstream f(name,std::ios::binary|std::ios::ate);if(!f)throw std::runtime_error("fixturemissing");size_t bytes=f.tellg();if(bytes%sizeof(T))throw std::runtime_error("dtype");f.seekg(0);std::vector<T>v(bytes/sizeof(T));if(!f.read((char*)v.data(),bytes))throw std::runtime_error("shortfixture");return v;}
struct State {Case c;std::vector<unsigned>h[11];unsigned*d[11];inArgsStruct a;resultsStruct r;State(Case q,std::vector<unsigned>&f):c(q){int width[]={16,16,4,4,1,9,1,1,1,1,1};size_t off=q.io;for(int k=0;k<11;k++){h[k].assign(size_t(q.n)*width[k]+32,GUARD);if(k<7){std::copy(f.begin()+off,f.begin()+off+size_t(q.n)*width[k],h[k].begin()+G);off+=size_t(q.n)*width[k];}else std::fill(h[k].begin()+G,h[k].end()-G,bits(-1234567.25f));CK(cudaMalloc(&d[k],h[k].size()*4));CK(cudaMemcpy(d[k],h[k].data(),h[k].size()*4,cudaMemcpyHostToDevice));}a.discountCurve=(bondsYieldTermStruct*)(d[0]+G);a.repoCurve=(bondsYieldTermStruct*)(d[1]+G);a.currDate=(bondsDateStruct*)(d[2]+G);a.maturityDate=(bondsDateStruct*)(d[3]+G);a.bondCleanPrice=(float*)(d[4]+G);a.bond=(bondStruct*)(d[5]+G);a.dummyStrike=(float*)(d[6]+G);r.dirtyPrice=(float*)(d[7]+G);r.accruedAmountCurrDate=(float*)(d[8]+G);r.cleanPrice=(float*)(d[9]+G);r.bondForwardVal=(float*)(d[10]+G);}void reset(){for(int k: {0,7,8,9,10})CK(cudaMemcpy(d[k],h[k].data(),h[k].size()*4,cudaMemcpyHostToDevice));CK(cudaDeviceSynchronize());}void run(){bonds<<<(c.n+255)/256,256>>>(a,r,c.n);CK(cudaGetLastError());CK(cudaDeviceSynchronize());}};
void capture_pre(State&s,std::vector<double>&out){for(int k=0;k<11;k++){auto v=s.h[k];CK(cudaMemcpy(v.data(),s.d[k],v.size()*4,cudaMemcpyDeviceToHost));for(unsigned u:v)out.push_back(k<7?double(u):double(fp(u)));}}
bool check_post(State&s,std::vector<double>&oracle,std::vector<double>&out,double&maxabs,double&maxrel){bool ok=true;auto q=s.c;for(int k=0;k<11;k++){auto v=s.h[k];CK(cudaMemcpy(v.data(),s.d[k],v.size()*4,cudaMemcpyDeviceToHost));for(size_t i=0;i<v.size();i++){bool interior=i>=G&&i<v.size()-G;bool rate=k==0&&interior&&(i-G)%16==0;bool output=k>=7;float actual=fp(v[i]);if(!interior)ok&=v[i]==GUARD;else if(k<7&&!rate)ok&=v[i]==s.h[k][i];else if(rate||output){int column=rate?4:k-7;int j=rate?int((i-G)/16):int(i-G);double want=oracle[q.oo+size_t(column)*q.n+j],err=fabs(double(actual)-want);maxabs=std::max(maxabs,err);maxrel=std::max(maxrel,err/std::max(1e-300,fabs(want)));bool pass=std::isfinite(actual)&&err<=.002+.0001*fabs(want);if(output&&k<=9)pass&=err<=.002;if(rate){double coupon=50.0*double(fp(s.h[5][G+size_t(j)*9+8]));double npv=(100+coupon)*pow(1+double(actual)/2,-1.0/180);pass&=fabs(npv-oracle[q.oo+j])<=.002;}if(!pass){printf("ORACLEFAIL n=%d field=%d row=%d actual=%.17g want=%.17g err=%.17g\n",q.n,column,j,double(actual),want,err);ok=false;break;}}out.push_back(rate||output?double(actual):double(v[i]));}}return ok;}
int main(){auto f=readv<unsigned>("input_u32.bin");auto o=readv<double>("oracle_f64.bin");std::vector<State*>states;for(auto c:cases){auto*s=new State(c,f);s->run();std::vector<double>out;double e=0,r=0;bool ok=check_post(*s,o,out,e,r);printf("WARM n=%d pass=%d maxabs=%.17g maxrel=%.17g\n",c.n,int(ok),e,r);fflush(stdout);if(!ok)throw std::runtime_error("independent_closedform_source_default_NPV_oracle");states.push_back(s);}for(int trial=1;trial<=5;trial++){std::vector<double>pre,post,times;double sec=0,maxabs=0,maxrel=0;bool ok=true;for(auto*s:states){s->reset();capture_pre(*s,pre);auto start=std::chrono::steady_clock::now();s->run();double t=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();sec+=t;times.push_back(t);ok&=check_post(*s,o,post,maxabs,maxrel);}pre.insert(pre.end(),post.begin(),post.end());std::string path="bonds_trial"+std::to_string(trial)+".bin";std::ofstream file(path,std::ios::binary);if(!file.write((char*)pre.data(),pre.size()*8))throw std::runtime_error("writeartifact");file.close();printf("STUDY_TRIAL {\"trial\":%d,\"correct\":%s,\"jit_excluded\":true,\"time_seconds\":%.12g,\"timing_region\":\"sum_four_original_dated_bond_kernel_and_device_completion\",\"max_abs_error\":%.17g,\"max_rel_error\":%.17g,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"shape\":[%zu],\"byte_order\":\"little\"},\"case_times_seconds\":[",trial,ok?"true":"false",sec,maxabs,maxrel,path.c_str(),pre.size(),pre.size());for(size_t i=0;i<times.size();i++)printf("%s%.12g",i?",":"",times[i]);printf("]}\n");fflush(stdout);}}
